const $=s=>document.querySelector(s),money=n=>Number(n).toLocaleString('pt-BR',{style:'currency',currency:'BRL'}),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let products=[],current=null,cart=[];try{cart=JSON.parse(localStorage.getItem('cozybed-cart')||'[]');if(!Array.isArray(cart))cart=[]}catch{}const short=p=>p.title.replace(/400 Fios 100% Algodão/gi,'').trim();const price=p=>Math.min(...p.variants.map(v=>+v.price));const normalize=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
function save(){try{localStorage.setItem('cozybed-cart',JSON.stringify(cart))}catch{}$('#count').textContent=cart.reduce((s,x)=>s+x.qty,0)}
const categories=[
{id:'kits',title:'Kits completos',description:'Peças que combinam. Conforto que se completa.',handles:['kit-lencol','kit-lencol-de-cima','kit-completo']},
{id:'lencois',title:'Lençóis & saia box',description:'A base de uma cama bem vestida, em cada detalhe.',handles:['lencol-c-elastico-solteiro','lencol-sem-elastico','saia-box']},
{id:'fronhas',title:'Fronhas & almofadas',description:'Pequenos toques para deixar tudo mais seu.',handles:['lencol-sem-elastico-copia','almofada','porta-almofada-de-corpo']},
{id:'duvets',title:'Duvets & capas',description:'Camadas de aconchego para completar o descanso.',handles:['capa-de-edredom','recheio-de-duvet-400-fios-100-algodao']}
];
const cardColors={"Branco":"#f3f0e8","Rose":"#c39aa4","Rosa Claro":"#e7c6c8","Cinza Claro":"#bfc2c0","Marfim":"#e8dfc8","Azul Claro":"#b2cad8","Verde":"#8a9982","Marrom":"#826659","Cinza Escuro":"#646a68","Bege":"#c6b59c"};
function productCard(p){return `<article class="product" data-card="${p.id}"><a class="product-visual" href="/products/${p.handle}/" aria-label="Ver ${esc(p.title)}"><img src="${p.localImage}" alt="${esc(p.title)}" loading="lazy">${p.title.startsWith('Kit')?'<span class="product-label">CONFORTO COMPLETO</span>':''}<span class="plus">↗</span></a><h3><a class="product-title-link" href="/products/${p.handle}/">${esc(short(p))}</a></h3><p class="material">400 fios · 100% algodão</p><span class="product-price">A partir de ${money(price(p))}</span><div class="swatches card-swatches" role="group" aria-label="Escolher cor de ${esc(short(p))}">${p.options[0].values.map(c=>`<button type="button" data-card-color="${esc(c)}" data-id="${p.id}" aria-label="${esc(c)}" aria-pressed="false" title="${esc(c)}"><i style="background:${cardColors[c]||'#eee'}"></i></button>`).join('')}<a href="/products/${p.handle}/">Ver detalhes</a></div></article>`}
function render(){const term=normalize($('#search').value),order=$('#sort').value;let count=0;$('#products').innerHTML=categories.map(c=>{let items=c.handles.map(h=>products.find(p=>p.handle===h)).filter(p=>p&&normalize(p.title).includes(term));if(order!=='featured')items.sort((a,b)=>order==='low'?price(a)-price(b):price(b)-price(a));if(!items.length)return '';count+=items.length;return `<section class="category-section" id="${c.id}" aria-labelledby="title-${c.id}"><div class="category-heading"><div><h3 id="title-${c.id}">${c.title}</h3><p>${c.description}</p></div><span>${items.length} produtos</span></div><div class="product-grid">${items.map(productCard).join('')}</div></section>`}).join('')||'<p class="empty">Nenhum produto encontrado. Experimente outro termo.</p>';$('#catalog-count').textContent=count+' produtos'+(term?' encontrados':' em 4 categorias');}
function renderCart(){$('#cart-items').innerHTML=cart.length?cart.map(x=>`<div class="cart-row"><img src="${esc(x.image)}" alt="${esc(x.title)}"><div>${esc(x.title)}<p>${esc(x.variant)}</p><button data-qty="-1" data-id="${x.id}" aria-label="Diminuir quantidade">−</button> <span>${x.qty}</span> <button data-qty="1" data-id="${x.id}" aria-label="Aumentar quantidade">+</button><br><button class="remove" data-remove="${x.id}">Remover</button></div><span>${money(x.price*x.qty)}</span></div>`).join(''):'<p class="empty">Sua sacola está esperando um pouco de conforto.<br>Explore a coleção e encontre seus essenciais.</p>';$('#cart-summary').innerHTML=cart.length?`<div class="total"><span>Subtotal</span><strong>${money(cart.reduce((s,x)=>s+x.price*x.qty,0))}</strong></div><p class="detail-note">Frete, disponibilidade e valor final confirmados na loja original.</p><a class="button dark" href="https://cozybedhome.com/cart/${cart.map(x=>x.id+':'+x.qty).join(',')}">Finalizar na Cozybed ↗</a><button class="more" id="continue">Continuar comprando</button>`:'<button class="button dark" id="continue">Explorar a coleção ↗</button>';$('#continue').onclick=()=>$('#cart-modal').close()}
function openCart(){renderCart();$('#cart-modal').showModal()}
document.addEventListener('click',e=>{const color=e.target.closest('[data-card-color]');if(color){const p=products.find(p=>p.id==color.dataset.id),v=p.variants.find(v=>v.option1===color.dataset.cardColor&&v.available)||p.variants.find(v=>v.option1===color.dataset.cardColor);const card=color.closest('.product');if(v){const img=card.querySelector('.product-visual img');img.src=v.featured_image?.src||p.images[0].src;img.alt=p.title+' — '+color.dataset.cardColor;card.querySelectorAll('.product-visual,.product-title-link,.card-swatches a').forEach(a=>a.href='/products/'+p.handle+'/?variant='+v.id);card.querySelectorAll('[data-card-color]').forEach(b=>{const active=b===color;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active))});card.querySelector('.material').textContent='400 fios · '+color.dataset.cardColor}}const cat=e.target.closest('a[href="#kits"],a[href="#colecao"]');if(cat&&$('#search').value){$('#search').value='';render()}const q=e.target.closest('[data-qty]');if(q){const item=cart.find(x=>x.id==q.dataset.id);item.qty+=Number(q.dataset.qty);cart=cart.filter(x=>x.qty>0);save();renderCart()}const r=e.target.closest('[data-remove]');if(r){cart=cart.filter(x=>x.id!=r.dataset.remove);save();renderCart()}});
document.querySelectorAll('dialog').forEach(d=>{d.querySelector('.close').onclick=()=>d.close();d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}})});$('#cart-open').onclick=openCart;$('#search-open').onclick=()=>{$('#search-box').hidden=false;location.hash='colecao';$('#search').focus()};$('#search-close').onclick=()=>{$('#search-box').hidden=true;$('#search').value='';render()};$('#search').oninput=render;$('#sort').onchange=render;
fetch('products.json').then(r=>{if(!r.ok)throw Error('catalog');return r.json()}).then(data=>{const rank=['kit-lencol','lencol-c-elastico-solteiro','lencol-sem-elastico-copia','capa-de-edredom'];products=data.sort((a,b)=>(rank.includes(a.handle)?rank.indexOf(a.handle):99)-(rank.includes(b.handle)?rank.indexOf(b.handle):99));cart=cart.filter(x=>{const p=products.find(p=>p.id===x.productId);const v=p?.variants.find(v=>v.id===x.id);if(v){x.price=v.price;return v.available}return false});save();render()}).catch(()=>{$('#products').innerHTML='<p>Não foi possível carregar a coleção. <a href="https://cozybedhome.com/collections/all">Acesse os produtos na loja original ↗</a></p>'});save();

const siteHeader=document.querySelector('header');
function syncHeader(){siteHeader.classList.toggle('scrolled',window.scrollY>24)}
window.addEventListener('scroll',syncHeader,{passive:true});window.addEventListener('pageshow',syncHeader);syncHeader();

const heroVideo=document.querySelector('.hero-video');const videoToggle=document.querySelector('.video-toggle');const reduceMotion=window.matchMedia('(prefers-reduced-motion: reduce)');
function syncVideoButton(){videoToggle.textContent=heroVideo.paused?'▶':'Ⅱ';videoToggle.setAttribute('aria-label',heroVideo.paused?'Reproduzir vídeo de fundo':'Pausar vídeo de fundo')}
function applyMotionPreference(){if(reduceMotion.matches){heroVideo.autoplay=false;heroVideo.pause()}else{heroVideo.autoplay=true;heroVideo.play().catch(()=>{})}syncVideoButton()}
videoToggle.addEventListener('click',()=>{if(heroVideo.paused)heroVideo.play().catch(()=>{});else heroVideo.pause()});heroVideo.addEventListener('play',syncVideoButton);heroVideo.addEventListener('pause',syncVideoButton);heroVideo.addEventListener('error',()=>{heroVideo.hidden=true;videoToggle.hidden=true});reduceMotion.addEventListener('change',applyMotionPreference);applyMotionPreference();

heroVideo.defaultPlaybackRate=1;heroVideo.playbackRate=1;
heroVideo.addEventListener('loadedmetadata',()=>{heroVideo.playbackRate=1});

if(new URLSearchParams(location.search).has('search')){$('#search-box').hidden=false;$('#search').focus()}
